import * as fs from "fs";
import PostgresDb = require("./dbHandler/postgres");
import MainProcess from "./data-transfers/main-process";

const raw = fs.readFileSync(".run.local.env", "utf8");
const env: Record<string, string> = {};
for (const line of raw.split(/\r?\n/)) {
  const s = line.trim();
  if (!s || s.startsWith("#")) continue;
  const idx = s.indexOf("=");
  if (idx > 0) env[s.slice(0, idx).trim()] = s.slice(idx + 1).trim();
}
console.log("VAULT_ENDPOINT set?", Boolean(env.VAULT_ENDPOINT));
console.log("TRANS_HIS_EXPORT_SOURCE:", env.TRANS_HIS_EXPORT_SOURCE);
console.log("TRANS_HIS_PG_HOST:", env.TRANS_HIS_PG_HOST, "PORT:", env.TRANS_HIS_PG_PORT, "DB:", env.TRANS_HIS_PG_DB, "USER:", env.TRANS_HIS_PG_USER, "PASS_LEN:", (env.TRANS_HIS_PG_PASS || "").length);

const logger: any = { info: console.log, warn: console.warn, error: console.error, debug: console.log };
const pg = new PostgresDb(logger);
pg.createConnection({
  alias: "trans-his-pg",
  host: env.TRANS_HIS_PG_HOST,
  port: Number(env.TRANS_HIS_PG_PORT),
  database: env.TRANS_HIS_PG_DB,
  username: env.TRANS_HIS_PG_USER,
  password: env.TRANS_HIS_PG_PASS,
  poolSize: Number(env.TRANS_HIS_PG_POOLSIZE) || 10
}, async (err, pool) => {
  if (err) {
    console.error("PG CONNECT ERROR:", err.message);
    process.exit(0);
  }
  console.log("PG CONNECTED! pool.ended=", (pool as any)?.ended, "in pool?", "ended" in (pool as any));
  const mp = new MainProcess({ logger } as any, logger, { "trans-his-pg": pool as any }, []);
  console.log("Models initialized:", Object.keys(mp.models));
  await pool?.end();
  process.exit(0);
});
